_MODEL_SRC = [None, 0.0]     # (path, mtime) when MODEL comes from the repo's data file (simulator), not baked in


def _refresh_model():
    """Simulator only: reload data/v3_model.json when it has been rebuilt (long-running workers stay fresh)."""
    try:
        import os as _os
        path = _MODEL_SRC[0] or _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "..", "data", "v3_model.json")
        mt = _os.path.getmtime(path)
        if mt != _MODEL_SRC[1]:
            import json as _json
            with open(path) as _f:
                m = _json.load(_f)
            MODEL.clear()
            MODEL.update(m)
            _MODEL_SRC[0], _MODEL_SRC[1] = path, mt
    except Exception:
        pass


if not MODEL:
    _refresh_model()


# ---------------------------------------------------------------- agent
class Agent:
    def __init__(self, params=None, seed=None):
        self.P = dict(P)
        if params:
            self.P.update(params)
        if _MODEL_SRC[0]:
            _refresh_model()
        self.rng = random.Random(seed)
        self.seat = 0
        self.n = 8
        self.total_hands = 1000
        self.spent = 0.0
        self.bank = self.P.get("bank_s", 8.5)
        self.hands_seen = 0
        self.st = {}
        self.post_decisions = 0
        self.hard_end = 0.0
        self.start = 2000
        self.ctx = None
        self.idll = {}
        self.post = {}

    def on_table_start(self, info):
        self.seat = info.get("seat", 0)
        self.n = info.get("num_players", 8)
        self.total_hands = info.get("hands", 1000) or 1000
        self.start = info.get("starting_stack", 2000) or 2000
        try:
            prebuild()
        except Exception:
            pass
        try:
            gc.collect()
            gc.freeze()
            gc.disable()   # avoid GC pauses inside act(); we collect between hands
        except Exception:
            pass

    def S(self, seat):
        s = self.st.get(seat)
        if s is None:
            s = self.st[seat] = Stats()
        return s

    # ------------------------------------------------------------- stats
    def on_hand_end(self, summary):
        try:
            self._learn(summary)
        except Exception:
            pass
        if self.hands_seen % 100 == 0:
            try:
                gc.collect(1)
            except Exception:
                pass

    def _learn(self, summary):
        self.hands_seen += 1
        hist = summary.get("history") or []
        seats = set(h.get("seat") for h in hist)
        bb = 20
        for h in hist:
            if h.get("action") == "big_blind":
                bb = h.get("amount") or 20
        for s in seats:
            self.S(s).hands += 1
        street = None
        cur = 0
        nraise = 0
        vp, pr = set(), set()
        opener = None
        sbs = bbs = None
        for h in hist:
            if h.get("action") == "small_blind":
                sbs = h.get("seat")
            elif h.get("action") == "big_blind":
                bbs = h.get("seat")
        for h in hist:
            a = h.get("action")
            s = h.get("seat")
            st = h.get("street")
            if st != street:
                street = st
                cur = bb if st == "preflop" else 0
                nraise = 0
                bets = {}
            if a in ("small_blind", "big_blind"):
                bets[s] = h.get("amount") or 0
                continue
            o = self.S(s)
            if st == "preflop":
                if a in ("call", "raise"):
                    vp.add(s)
                if nraise >= 1 and a in ("fold", "call", "raise"):
                    o.f3 += 1
                    if a == "fold":
                        o.f3fold += 1
                    if nraise >= 2 and s == opener:
                        o.o3 += 1
                        if a == "fold":
                            o.o3fold += 1
                    if nraise == 1 and s in (sbs, bbs) and s != opener:
                        o.bdef += 1
                        if a == "fold":
                            o.bfold += 1
                if a == "raise" and nraise == 0:
                    opener = s
                if a == "raise":
                    pr.add(s)
                    if (h.get("amount") or 0) >= 600:
                        o.big += 1
            else:
                if a == "raise":
                    o.pbet += 1
                elif a == "call":
                    o.pcall += 1
                elif a == "check":
                    o.pcheck += 1
                if cur > 0 and a in ("fold", "call", "raise"):
                    o.faced += 1
                    if a == "fold":
                        o.ffold += 1
            if a == "raise":
                cur = h.get("amount") or cur
                nraise += 1
        if self.P["ident"] and MODEL.get("bots"):
            try:
                self._id_learn(hist, bb)
            except Exception:
                pass
        for s in vp:
            self.S(s).vpip += 1
        for s in pr:
            self.S(s).pfr += 1
        shown = summary.get("shown") or {}
        aggr = set(h.get("seat") for h in hist if h.get("action") == "raise" and h.get("street") in ("turn", "river"))
        bd = [to_int(c) for c in (summary.get("board") or [])]
        for k in shown:
            try:
                o = self.S(int(k))
                o.sd += 1
                if int(k) in aggr and len(bd) == 5:
                    hc = shown[k]
                    o.sda += 1
                    if level_of(to_int(hc[0]), to_int(hc[1]), bd) <= 1:
                        o.sdw += 1
            except Exception:
                pass

    def _id_learn(self, hist, bb):
        street, pot, bets, raised = None, 0, {}, False
        touched = set()
        for h in hist:
            a, s, st = h.get("action"), h.get("seat"), h.get("street")
            amt = h.get("amount") or 0
            if st != street:
                street, bets = st, {}
            if a in ("small_blind", "big_blind"):
                bets[s] = amt
                pot += amt
                continue
            cur = max(bets.values()) if bets else 0
            if a == "raise":
                if st == "preflop" and not raised:
                    self._id_obs(s, "opens", str(amt))
                    touched.add(s)
                elif st != "preflop" and cur == 0:
                    frac = (amt - bets.get(s, 0)) / float(max(1, pot))
                    self._id_obs(s, "pbets", "%.2f" % (round(frac / 0.05) * 0.05))
                    touched.add(s)
                raised = raised or st == "preflop"
                pot += amt - bets.get(s, 0)
                bets[s] = amt
            elif a == "call":
                pot += amt
                bets[s] = bets.get(s, 0) + amt
        for s in touched:
            if s != self.seat:
                self._id_post(s)

    def pri(self, s, key, default, k):
        """(prior value, prior weight): the identified bot's profile when we know who sits there."""
        q = self.post.get(s)
        if not q:
            return default, k
        return q[key], k + self.P["id_k"] * q["_conf"]

    def vpip(self, s):
        o = self.S(s)
        pv, k = self.pri(s, "vpip", self.P["pri_vpip"], 12)
        return (o.vpip + pv * k) / (o.hands + k)

    def pfr(self, s):
        o = self.S(s)
        pv, k = self.pri(s, "pfr", self.P["pri_pfr"], 12)
        return (o.pfr + pv * k) / (o.hands + k)

    def bigrate(self, s):
        o = self.S(s)
        pv, k = self.pri(s, "big", 0.05, 10)
        return (o.big + pv * k) / (o.hands + k)

    def fold3(self, s):
        """(rate, n): how often seat s folds its OWN open to a re-raise."""
        o = self.S(s)
        pv, k = self.pri(s, "f3", 0.5, 4)
        return (o.o3fold + pv * k) / (o.o3 + k), o.o3 + (k - 4)

    def blindfold(self, s):
        """(rate, n): how often seat s, in a blind, folds to a single open."""
        o = self.S(s)
        return (o.bfold + 0.6 * 6) / (o.bdef + 6), o.bdef

    def ftr(self, s):
        """Preflop: how often seat s folds when facing a raise."""
        o = self.S(s)
        pv, k = self.pri(s, "ftr", 0.75, 10)
        return (o.f3fold + pv * k) / (o.f3 + k)

    def ftb(self, s):
        o = self.S(s)
        pv, k = self.pri(s, "ftb", self.P["pri_ftb"], 8)
        return (o.ffold + pv * k) / (o.faced + k)

    def sdmult(self, s):
        o = self.S(s)
        pr, k = self.P["sd_prior"], self.P["sd_k"]
        return clamp((o.sdw + pr * k) / (o.sda + k) / pr, 0.35, 2.5)

    def af(self, s):
        o = self.S(s)
        pv, k = self.pri(s, "af", 0.3, 10)
        return (o.pbet + pv * k) / (o.pbet + o.pcall + o.pcheck + k)

    # ------------------------------------------------------------- identification
    def _id_obs(self, s, kind, key):
        """One fingerprint observation (kind 'opens' or 'pbets') for seat s."""
        bots = MODEL.get("bots")
        if not bots:
            return
        ll = self.idll.get(s)
        if ll is None:
            ll = self.idll[s] = {}
        u = 0.02
        tot = 0.0
        for b, prof in bots.items():
            pb = prof[kind].get(key, 0.0)
            tot += pb
            ll[b] = ll.get(b, 0.0) + _log(0.85 * pb + 0.15 * u)
        ll["_pop"] = ll.get("_pop", 0.0) + _log(0.85 * tot / len(bots) + 0.15 * u)

    def _id_post(self, s):
        bots = MODEL.get("bots")
        ll = self.idll.get(s)
        if not bots or not ll:
            return
        W = sum(p["w"] for p in bots.values())
        lp = {b: v + _log(0.8 * bots[b]["w"] / W) if b != "_pop" else v + _log(0.2) for b, v in ll.items()}
        mx = max(lp.values())
        ex = {b: _exp(v - mx) for b, v in lp.items()}
        Z = sum(ex.values())
        popm = MODEL["popstats"]
        q = {}
        for key in ("vpip", "pfr", "big", "f3", "ftr", "ftb", "af", "bluff"):
            v = 0.0
            for b, e in ex.items():
                v += e * (bots[b][key] if b != "_pop" else popm[key])
            q[key] = v / Z
        best = max((e for b, e in ex.items() if b != "_pop"), default=0.0) / Z
        q["_conf"] = best
        self.post[s] = q

    # ------------------------------------------------------------- time
    def budget(self):
        left = self.bank - self.spent
        if left <= 0.4:
            return 0.0
        hands_left = max(1, self.total_hands - self.hands_seen)
        per = left / (hands_left * 0.9 + 1)
        return clamp(per, 0.0, self.P["max_ms"] / 1000.0)

    # ------------------------------------------------------------- api
    def act(self, state):
        t0 = time.perf_counter()
        self.hard_end = t0 + self.P.get("hard_ms", 3.0) / 1000.0
        try:
            out = self.decide(state)
        except Exception:
            if DEBUG:
                raise
            out = None
        out = self.legalise(state, out)
        self.spent += time.perf_counter() - t0 + 0.0002
        return out

    def legalise(self, state, out):
        legal = state.get("legal_actions") or []
        to_call = state.get("to_call") or 0
        if not isinstance(out, dict):
            out = {}
        a = out.get("action")
        if a == "raise" or a == "all_in":
            if "raise" in legal:
                lo, hi = state.get("min_raise_to"), state.get("max_raise_to")
                if lo is None or hi is None:
                    return {"action": "all_in"}
                if a == "all_in":
                    return {"action": "raise", "amount": int(hi)}
                try:
                    amt = int(out.get("amount", lo))
                except Exception:
                    amt = lo
                return {"action": "raise", "amount": int(max(lo, min(hi, amt)))}
            a = "call"
        if a == "call":
            if to_call > 0 and "call" in legal:
                return {"action": "call"}
            return {"action": "check"} if to_call == 0 else {"action": "fold"}
        return {"action": "check"} if to_call == 0 else {"action": "fold"}

    def decide(self, state):
        if state["street"] == "preflop":
            return self.preflop(state)
        return self.postflop(state)

    # ------------------------------------------------------------- ranges
    def pf_range(self, state, j):
        """(lo, hi) fraction of ALLC that seat j's preflop actions suggest."""
        raised = False
        threeb = False
        called = False
        big = False
        nr = 0
        for h in state["history"]:
            if h["street"] != "preflop":
                break
            a = h["action"]
            if h["seat"] == j:
                if a == "raise":
                    raised = True
                    if nr >= 1:
                        threeb = True
                    if (h.get("amount") or 0) >= 600:
                        big = True
                elif a == "call":
                    called = True
            if a == "raise":
                nr += 1
        if big:
            f = clamp(max(self.bigrate(j), self.pfr(j) * 0.25), 0.025, 0.6)
            return 0.0, f
        if threeb:
            return 0.0, clamp(self.pfr(j) * self.P["r3_mult"], 0.025, 0.4)
        if raised:
            return 0.0, clamp(self.pfr(j), 0.04, 0.7)
        if called:
            hi = clamp(self.vpip(j), 0.1, 1.0)
            lo = clamp(self.pfr(j) * self.P["call_lo"], 0.0, hi * 0.5) if nr else 0.0
            return lo, hi
        return 0.0, 1.0

    # ------------------------------------------------------------- preflop
    def preflop(self, state):
        hole = state["hole_cards"]
        key = hand_key(hole)
        pct = CLS_PCT[key]
        bb = state["big_blind"]
        tc = state["to_call"]
        n = len(state["stacks"])
        me = state["seat"]
        btn = state["button"]
        pos = (me - btn) % n          # 0 BTN 1 SB 2 BB 3 UTG ...
        bets = state["bets"]
        stack = state["stacks"][me] + bets[me]
        cur = max(bets)
        pot = state["pot"]
        hist = [h for h in state["history"] if h["street"] == "preflop"]
        raises = [h for h in hist if h["action"] == "raise"]
        nlimp = sum(1 for h in hist if h["action"] == "call")
        folded = state["folded"]
        live = [i for i in range(n) if not folded[i] and i != me]
        acted = set(h["seat"] for h in hist if h["action"] not in ("small_blind", "big_blind"))
        behind = [i for i in live if i not in acted and i != me]

        if not raises:
            # open / iso / BB option
            if pos == 2 and tc == 0:
                if pct <= self.P["bb_raise"]:
                    return self.r(bb * (self.P["open_size"] + 1 + nlimp))
                return {"action": "check"}
            pk = {0: "o_btn", 1: "o_sb"}.get(pos)
            if pk is None:
                from_end = (n - pos) % n  # CO=1, HJ=2, ...
                pk = {1: "o_co", 2: "o_hj", 3: "o_mp"}.get(from_end, "o_ep")
            f = self.P[pk]
            if behind:
                av = sum(self.vpip(i) for i in behind) / len(behind)
                f *= clamp(1 + self.P["steal_k"] * (self.P["pri_vpip"] - av), 0.6, 2.2)
            if nlimp:
                f = max(f * self.P["iso_mult"], 0.06)
            elif self.P.get("q_steal") and behind and pos in (0, 1, n - 1):
                ok = True
                for i in behind:
                    rate, cnt = self.blindfold(i) if (i - btn) % n in (1, 2) else (self.ftr(i), 99)
                    if cnt < self.P.get("q_min_obs", 8) or rate < self.P["q_steal_ftr"]:
                        ok = False
                if ok:
                    f = max(f, self.P["q_steal_f"])
            if pct <= f:
                tabv = sum(self.vpip(i) for i in live) / max(1, len(live))
                size = self.P["open_size"] + (self.P["loose_add"] if tabv > 0.4 else 0) + nlimp
                if pos == 1:
                    size += 0.5
                return self.r(bb * size)
            if nlimp and tc <= bb and pct <= self.P["overlimp"] and pos in (0, 1, n - 1):
                return {"action": "call"}
            if pos == 1 and nlimp == 0 and tc <= bb // 2 and pct <= self.P["sb_limp"]:
                return {"action": "call"}
            return {"action": "check"} if tc == 0 else {"action": "fold"}

        # facing raise(s)
        raiser = raises[-1]["seat"]
        lo, hi = self.pf_range(state, raiser)
        e = eq_vs_range(key, hi)
        others = [i for i in live if i != raiser and (bets[i] > bb or i in acted and bets[i] >= cur)]
        extra = len([i for i in others if bets[i] >= cur])
        if extra:
            e = e ** (1 + self.P["multi_exp"] * extra)
        order = lambda s: (s - btn - 1) % n
        ip = order(me) > order(raiser)
        allin_call = tc >= state["stacks"][me]
        real = 1.0 if allin_call else (self.P["real_ip"] if ip else self.P["real_oop"])
        if pos == 1 and not allin_call:
            real = self.P["real_sb"]
        if pct <= 0.03:
            real = 1.0
        ev_call = e * real * (pot + tc) - tc
        nr = len(raises)
        if nr >= 2 and tc > 0.25 * pot and any(h["seat"] == me for h in raises):
            # we raised and were re-raised: real rounds show hands below the top slice lose more by continuing
            if pct > (self.P["vs3_pct"] if nr == 2 else self.P["vs4_pct"]):
                return {"action": "fold"}
        if (self.P.get("q_3bet") and nr == 1 and not extra and "raise" in state["legal_actions"]
                and pct <= self.P["q_3bet_range"] and self.fold3(raiser)[1] >= self.P.get("q_min_obs", 8)
                and self.fold3(raiser)[0] >= self.P["q_3bet_ftr"] and cur <= 5 * bb):
            tgt = cur * (self.P["3b_ip"] if ip else self.P["3b_oop"]) + (pot - cur - bets[me]) * 0.5
            if tgt < stack * 0.35:
                return self.r(tgt)
        if "raise" in state["legal_actions"] and nr < 4:
            thr = self.P["eq_3b"] if nr == 1 else self.P["eq_4b"]
            if e >= thr and not (extra and e < thr + 0.05):
                tgt = cur * (self.P["3b_ip"] if ip else self.P["3b_oop"]) + (pot - cur - bets[me]) * 0.5
                if nr >= 2 or tgt >= stack * 0.35:
                    return {"action": "all_in"}
                return self.r(tgt)
        if ev_call > self.P["pf_call_margin"] * bb:
            return {"action": "call"}
        return {"action": "fold"}

    def r(self, amt):
        return {"action": "raise", "amount": int(amt)}

    # ------------------------------------------------------------- postflop
    def opp_models(self, state, me):
        folded = state["folded"]
        stacks = state["stacks"]
        hist = state["history"]
        street = state["street"]
        models = []
        lastagg = self._last_aggr(hist) if (self.P["size_read"] > 0 and MODEL.get("pop")) else {}
        for j in range(len(folded)):
            if j == me or folded[j]:
                continue
            lo, hi = self.pf_range(state, j)
            agg = 0
            calls = 0
            raise_over = False
            for h in hist:
                if h["seat"] != j or h["street"] == "preflop":
                    continue
                if h["action"] == "raise":
                    agg += 1
                elif h["action"] == "call":
                    calls += 1
            # did j raise over someone else's bet this street?
            seen_bet = False
            for h in hist:
                if h["street"] != street:
                    continue
                if h["action"] == "raise":
                    if h["seat"] == j and seen_bet:
                        raise_over = True
                    seen_bet = True
            bl = clamp(self.P["bluff_base"] + (self.af(j) - 0.3) * self.P["bluff_af"], 0.04, 0.9)
            if agg >= 2 or raise_over:
                w = (bl * self.P["w_r_air"], self.P["w_r_weak"], self.P["w_r_mid"], 1.0)
            else:
                w = (bl, self.P["w_b_weak"], self.P["w_b_mid"], 1.0)
            m = self.ftb(j) / self.P["pri_ftb"]
            cont = (clamp(1 - (1 - self.P["c_air"]) * m, 0.0, 1), clamp(1 - (1 - self.P["c_weak"]) * m, 0.0, 1),
                    clamp(1 - (1 - self.P["c_mid"]) * m, 0.0, 1), 1.0)
            if agg >= 1 and self.P["sd_cal"]:
                sm = self.sdmult(j)
                w = (w[0] * sm, min(1.0, w[1] * sm), w[2], w[3])
            if agg >= 1 and j in lastagg:
                w = self._size_weights(j, lastagg[j], w)
            if agg >= 2 or raise_over:
                pass
            elif agg == 0 and calls:
                w = (max(0.02, cont[0]), max(0.05, cont[1]), max(0.1, cont[2]), 1.0)
            elif agg == 0:
                w = (1.0, 1.0, 1.0, 1.0)
            allin = stacks[j] == 0
            bj = state["bets"][j]
            models.append((j, int(lo * NC), max(int(lo * NC) + 6, int(hi * NC)), w, cont, allin,
                           bj, bj + stacks[j], self.start - stacks[j]))
        return models

    def _last_aggr(self, hist):
        """seat -> (street, size bucket) of its latest postflop bet/raise this hand."""
        out = {}
        street, pot, bets = None, 0, {}
        for h in hist:
            a, s, st = h.get("action"), h.get("seat"), h.get("street")
            amt = h.get("amount") or 0
            if st != street:
                street, bets = st, {}
            if a in ("small_blind", "big_blind"):
                bets[s] = amt
                pot += amt
                continue
            cur = max(bets.values()) if bets else 0
            if a == "raise":
                if st != "preflop":
                    out[s] = (st, size_bucket((amt - bets.get(s, 0)) / float(max(1, pot)), cur > 0))
                pot += amt - bets.get(s, 0)
                bets[s] = amt
            elif a == "call":
                pot += amt
                bets[s] = bets.get(s, 0) + amt
        return out

    def _size_weights(self, j, sb, w):
        st, b = sb
        pop = MODEL["pop"]
        tab = pop["lvl"].get(st, {}).get(str(b))
        if not tab:
            return w
        base = pop["base"][st]
        f = [tab[L] / max(1e-3, base[L]) for L in range(4)]
        q = self.post.get(j)
        if q:
            br = clamp(q["bluff"], 0.4, 2.5) ** q["_conf"]
            f[0] *= br
            f[1] *= br
        mx = max(f)
        a = self.P["size_read"]
        return tuple(max(1e-3, w[L]) ** (1 - a) * max(1e-3, f[L] / mx) ** a for L in range(4))

    def simulate(self, hole, board, models, cands, my_bet, pot, raising, budget):
        """Weighted MC over opponents' ranges.

        Returns (eq, evs): eq = weighted showdown share vs all live opponents;
        evs[i] = expected chips back (minus our extra chips) for betting/raising
        to cands[i], where each opponent continues according to its continue
        model and only continuing hands contest the pot.
        """
        rng = self.rng
        my = [to_int(c) for c in hole]
        bd = [to_int(c) for c in board]
        dead = set(my) | set(bd)
        deck = [c for c in range(52) if c not in dead]
        need = 5 - len(bd)
        bprod = 1
        bsc = [0, 0, 0, 0]
        bsm = [0, 0, 0, 0]
        brc = [0] * 13
        for c in bd:
            bprod *= CP[c]
            bsc[c & 3] += 1
            bsm[c & 3] |= CB[c]
            brc[c >> 2] += 1
        top = max(c >> 2 for c in bd)
        bpairs = set(r for r in range(13) if brc[r] >= 2)
        draw_st = need > 0
        k = len(models)
        fvr = self.P["fold_vs_raise"] if raising else 1.0
        nc = len(cands)
        adds = [R - my_bet for R in cands]
        sizes = [max(0.05, a / float(max(1, pot))) for a in adds]
        exps = [min(2.5, (sz / 0.6) ** self.P["size_exp"]) for sz in sizes]
        fks = [1.0] * nc
        if self.P["fold_cal"] and MODEL.get("pop") and not raising:
            stn = {3: "flop", 4: "turn", 5: "river"}[len(bd)]
            base = MODEL["pop"]["base"][stn]
            cb = (self.P["c_air"], self.P["c_weak"], self.P["c_mid"])
            for ci in range(nc):
                tgt = MODEL["pop"]["fold"][stn].get(str(size_bucket(sizes[ci], False)))
                if tgt is None:
                    continue
                e = exps[ci]
                fp = sum(base[L] * (1 - cb[L] ** e) for L in range(3)) + base[3] * (0.0 if e < 2.0 else 0.08)
                fks[ci] = clamp(tgt / max(0.02, fp), 0.4, 2.5)
        conts = []
        contrib = []
        for m in models:
            cont, allin, bet_j, cap_j = m[4], m[5], m[6], m[7]
            row = []
            crow = []
            for ci in range(nc):
                e = exps[ci]
                if allin:
                    row.append((1.0, 1.0, 1.0, 1.0))
                else:
                    cc = (cont[0] ** e, cont[1] ** e, cont[2] ** e, 1.0 if e < 2.0 else 0.92)
                    if fks[ci] != 1.0:
                        fk = fks[ci]
                        cc = tuple(clamp(1 - (1 - x) * fk, 0.0, 1.0) for x in cc)
                    if fvr != 1.0:
                        cc = tuple(clamp(1 - (1 - x) * fvr, 0.0, 1.0) for x in cc)
                    row.append(cc)
                crow.append(max(0, min(cands[ci], cap_j) - bet_j))
            conts.append(row)
            contrib.append(crow)
        caps = [m[7] for m in models]
        hc, dead_c, tcall = self.ctx
        tot = [m[8] for m in models]
        # side-pot math needed only if an all-in player is below what the others will put in
        sp_call = tcall > 0 and any(m[5] and m[8] < hc + tcall for m in models)
        CV = 0.0
        W = 0.0
        E = 0.0
        EV = [0.0] * nc
        sims = 0
        now = time.perf_counter()
        t_end = now + budget
        hard = self.hard_end if self.hard_end > 0 else now + 0.003
        RTl = RT
        FLl = FL
        mp = CP[my[0]] * CP[my[1]]
        while True:
            for _ in range(2):
                used = set(dead)
                hands = []
                for m in models:
                    lo, hi = m[1], m[2]
                    for _t in range(40):
                        h = ALLC[rng.randrange(lo, hi)]
                        if h[0] not in used and h[1] not in used:
                            break
                    else:
                        while True:
                            h = tuple(rng.sample(deck, 2))
                            if h[0] not in used and h[1] not in used:
                                break
                    used.add(h[0])
                    used.add(h[1])
                    hands.append(h)
                w = 1.0
                lv = []
                for idx in range(k):
                    h1, h2 = hands[idx]
                    v = RTl[bprod * CP[h1] * CP[h2]]
                    s1, s2 = h1 & 3, h2 & 3
                    for s in range(4):
                        cnt = bsc[s] + (s1 == s) + (s2 == s)
                        if cnt >= 5:
                            fv = FLl[bsm[s] | (CB[h1] if s1 == s else 0) | (CB[h2] if s2 == s else 0)]
                            if fv > v:
                                v = fv
                        elif cnt == 4 and draw_st and (s1 == s or s2 == s):
                            v = -1 if v < (1 << 20) else v
                    if v == -1:
                        L = 1
                    else:
                        cat = v >> 20
                        if cat >= 4:
                            L = 3
                        elif cat == 3:
                            L = 0 if brc[(v >> 8) & 15] >= 3 else 3
                        elif cat == 2:
                            p1, p2 = (v >> 8) & 15, (v >> 4) & 15
                            if p1 in bpairs and p2 in bpairs:
                                L = 0
                            elif p1 in bpairs or p2 in bpairs:
                                o = p2 if p1 in bpairs else p1
                                L = 2 if o >= top else 1
                            else:
                                L = 3
                        elif cat == 1:
                            p = (v >> 12) & 15
                            L = 0 if p in bpairs else (2 if p >= top else 1)
                        else:
                            L = 0
                    lv.append(L)
                    w *= models[idx][3][L]
                if w < 1e-4:
                    w = 1e-4
                if need:
                    run = []
                    while len(run) < need:
                        c = deck[rng.randrange(len(deck))]
                        if c not in used:
                            used.add(c)
                            run.append(c)
                    full = bd + run
                else:
                    full = bd
                fp = 1
                fsc = [0, 0, 0, 0]
                fsm = [0, 0, 0, 0]
                for c in full:
                    fp *= CP[c]
                    fsc[c & 3] += 1
                    fsm[c & 3] |= CB[c]
                fs = -1
                for s in range(4):
                    if fsc[s] >= 3:
                        fs = s
                mv = RTl[fp * mp]
                if fs >= 0:
                    a, b = my
                    if fsc[fs] + ((a & 3) == fs) + ((b & 3) == fs) >= 5:
                        fv = FLl[fsm[fs] | (CB[a] if (a & 3) == fs else 0) | (CB[b] if (b & 3) == fs else 0)]
                        if fv > mv:
                            mv = fv
                ov = []
                best = 0
                ties = 0
                for (h1, h2) in hands:
                    v = RTl[fp * CP[h1] * CP[h2]]
                    if fs >= 0 and fsc[fs] + ((h1 & 3) == fs) + ((h2 & 3) == fs) >= 5:
                        fv = FLl[fsm[fs] | (CB[h1] if (h1 & 3) == fs else 0) | (CB[h2] if (h2 & 3) == fs else 0)]
                        if fv > v:
                            v = fv
                    ov.append(v)
                    if v > best:
                        best = v
                        ties = 0
                    elif v == best:
                        ties += 1
                sh = 1.0 if mv > best else (1.0 / (ties + 2) if mv == best else 0.0)
                W += w
                E += w * sh
                if sp_call:
                    tgt = hc + tcall
                    parts = [(tgt, mv)]
                    dd = list(dead_c)
                    for idx in range(k):
                        m = models[idx]
                        if m[5] or tot[idx] >= tgt:
                            parts.append((tot[idx], ov[idx]))
                        elif rng.random() < m[4][lv[idx]]:
                            parts.append((min(tgt, m[8] + m[7] - m[6]), ov[idx]))
                        else:
                            dd.append(tot[idx])
                    CV += w * (layered_win(parts, 0, dd) - tcall)
                else:
                    CV += w * (sh * (pot + tcall) - tcall)
                if nc:
                    if k == 1:
                        cap0 = caps[0]
                        for ci in range(nc):
                            c = conts[0][ci][lv[0]]
                            add = adds[ci]
                            if cap0 >= cands[ci]:
                                called = sh * (pot + add + contrib[0][ci]) - add
                            else:
                                called = layered_win([(hc + add, mv), (tot[0] + contrib[0][ci], ov[0])], 0, dead_c) - add
                            EV[ci] += w * ((1 - c) * pot + c * called)
                    else:
                        us = [rng.random() for _ in range(k)]
                        for ci in range(nc):
                            callers = [idx for idx in range(k) if us[idx] < conts[idx][ci][lv[idx]]]
                            if not callers:
                                EV[ci] += w * pot
                                continue
                            bv = 0
                            bt = 0
                            mcap = 0
                            ctot = 0
                            for idx in callers:
                                v = ov[idx]
                                if v > bv:
                                    bv = v
                                    bt = 0
                                elif v == bv:
                                    bt += 1
                                if caps[idx] > mcap:
                                    mcap = caps[idx]
                                ctot += contrib[idx][ci]
                            add = adds[ci]
                            if all(caps[idx] >= cands[ci] for idx in callers):
                                s2 = 1.0 if mv > bv else (1.0 / (bt + 2) if mv == bv else 0.0)
                                EV[ci] += w * (s2 * (pot + add + ctot) - add)
                            else:
                                parts = [(hc + add, mv)] + [(tot[idx] + contrib[idx][ci], ov[idx]) for idx in callers]
                                dd = dead_c + [tot[idx] for idx in range(k) if idx not in callers]
                                EV[ci] += w * (layered_win(parts, 0, dd) - add)
                sims += 1
            now = time.perf_counter()
            if sims >= self.P["max_sims"] or now > hard or (now > t_end and sims >= 8):
                break
        self.last_sims = sims
        self.call_ev = CV / W
        return E / W, [x / W for x in EV]

    def postflop(self, state):
        me = state["seat"]
        pot = state["pot"]
        tc = state["to_call"]
        bets = state["bets"]
        my_bet = bets[me]
        cur = max(bets)
        n = len(bets)
        btn = state["button"]
        street = state["street"]
        lo_r, hi_r = state.get("min_raise_to"), state.get("max_raise_to")
        can_raise = "raise" in state["legal_actions"] and lo_r is not None and hi_r is not None
        models = self.opp_models(state, me)
        if not models:
            return {"action": "check"}
        order = lambda s: (s - btn - 1) % n
        ip = all(order(me) > order(m[0]) for m in models)
        cands = []
        if can_raise:
            fr = list(self.P["bet_sizes"] if tc == 0 else self.P["raise_sizes"])
            if tc == 0:
                if street == "river":
                    fr += self.P.get("q_river_extra", [])
                fr += self.P.get("q_small_extra", [])
            base = pot if tc == 0 else pot + tc
            seen = set()
            for f in fr:
                R = max(lo_r, min(hi_r, int(cur + f * base)))
                if R not in seen:
                    seen.add(R)
                    cands.append(R)
            if hi_r not in seen and (hi_r - my_bet) <= self.P["shove_spr"] * pot:
                cands.append(hi_r)
        b = self.budget()
        if b <= 0:
            b = 0.0003
        live = set(m[0] for m in models) | {me}
        dead_c = [self.start - state["stacks"][j] for j in range(n) if j not in live]
        self.ctx = (self.start - state["stacks"][me], dead_c, tc)
        e, evs = self.simulate(state["hole_cards"], state["board"], models, cands, my_bet, pot, tc > 0, b)
        self.last_e = e
        if (tc == 0 and self.P.get("q_trap") and not ip and street != "river" and e >= self.P["q_trap_eq"]
                and any(self.af(m[0]) >= self.P["q_trap_af"] and not m[5] for m in models)):
            return {"action": "check"}
        if tc == 0:
            best = e * pot * (self.P["chk_ip"] if ip else self.P["chk_oop"])
            act = {"action": "check"}
            bonus = -self.P["bet_margin"] * pot
            for R, ev in zip(cands, evs):
                if ev + bonus > best:
                    best = ev + bonus
                    act = self.r(R)
            return act
        ev_call = self.call_ev
        if street != "river":
            ev_call -= self.P["call_tax"] * pot
        best = 0.0
        act = {"action": "fold"}
        if ev_call > best:
            best = ev_call
            act = {"action": "call"}
        bonus = -self.P["raise_margin"] * pot
        for R, ev in zip(cands, evs):
            if ev + bonus > best:
                best = ev + bonus
                act = self.r(R)
        return act
